import os
from typing import Any, Dict, List, Optional

import boto3


def _get_block_text(block: Dict[str, Any], block_map: Dict[str, Dict[str, Any]]) -> str:
    text_parts: List[str] = []
    for rel in block.get("Relationships", []):
        if rel.get("Type") == "CHILD":
            for child_id in rel.get("Ids", []):
                child = block_map.get(child_id)
                if not child:
                    continue
                if child.get("BlockType") == "WORD":
                    text_parts.append(child.get("Text", ""))
                elif child.get("BlockType") == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                    text_parts.append("X")
    return " ".join(part for part in text_parts if part).strip()


def _extract_table(
    table_block: Dict[str, Any],
    block_map: Dict[str, Dict[str, Any]],
) -> Dict[str, Any]:
    cell_blocks: List[Dict[str, Any]] = []
    for rel in table_block.get("Relationships", []):
        if rel.get("Type") == "CHILD":
            for child_id in rel.get("Ids", []):
                child = block_map.get(child_id)
                if child and child.get("BlockType") == "CELL":
                    cell_blocks.append(child)

    max_row = max((cell.get("RowIndex", 0) for cell in cell_blocks), default=0)
    max_col = max((cell.get("ColumnIndex", 0) for cell in cell_blocks), default=0)
    grid: List[List[str]] = [["" for _ in range(max_col)] for _ in range(max_row)]

    cells_out: List[Dict[str, Any]] = []
    for cell in cell_blocks:
        row = cell.get("RowIndex", 1)
        col = cell.get("ColumnIndex", 1)
        text = _get_block_text(cell, block_map)
        if row > 0 and col > 0:
            grid[row - 1][col - 1] = text
        cells_out.append(
            {
                "row": row,
                "column": col,
                "row_span": cell.get("RowSpan", 1),
                "column_span": cell.get("ColumnSpan", 1),
                "text": text,
                "confidence": cell.get("Confidence"),
                "geometry": cell.get("Geometry"),
            }
        )

    return {
        "id": table_block.get("Id"),
        "confidence": table_block.get("Confidence"),
        "geometry": table_block.get("Geometry"),
        "cells": cells_out,
        "grid": grid,
    }


def extract_document_layout(
    *,
    file_path: Optional[str] = None,
    s3_bucket: Optional[str] = None,
    s3_key: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    if not file_path and not (s3_bucket and s3_key):
        raise ValueError("Provide either file_path or both s3_bucket and s3_key.")

    client = boto3.client(
        "textract",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
    )

    document: Dict[str, Any]
    if file_path:
        with open(file_path, "rb") as f:
            document = {"Bytes": f.read()}
    else:
        document = {"S3Object": {"Bucket": s3_bucket, "Name": s3_key}}

    response = client.analyze_document(
        Document=document,
        FeatureTypes=["TABLES", "LAYOUT"],
    )

    blocks: List[Dict[str, Any]] = response.get("Blocks", [])
    block_map: Dict[str, Dict[str, Any]] = {b["Id"]: b for b in blocks if "Id" in b}

    pages: List[Dict[str, Any]] = []
    lines: List[Dict[str, Any]] = []
    words: List[Dict[str, Any]] = []
    tables: List[Dict[str, Any]] = []
    layout_elements: List[Dict[str, Any]] = []

    for block in blocks:
        block_type = block.get("BlockType")

        if block_type == "PAGE":
            pages.append(
                {
                    "id": block.get("Id"),
                    "page": block.get("Page"),
                    "geometry": block.get("Geometry"),
                }
            )
        elif block_type == "LINE":
            lines.append(
                {
                    "id": block.get("Id"),
                    "page": block.get("Page"),
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry"),
                }
            )
        elif block_type == "WORD":
            words.append(
                {
                    "id": block.get("Id"),
                    "page": block.get("Page"),
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry"),
                }
            )
        elif block_type == "TABLE":
            tables.append(_extract_table(block, block_map))
        elif block_type and block_type.startswith("LAYOUT_"):
            layout_elements.append(
                {
                    "id": block.get("Id"),
                    "type": block_type,
                    "page": block.get("Page"),
                    "text": _get_block_text(block, block_map),
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry"),
                }
            )

    return {
        "provider": "aws_textract",
        "api": "analyze_document",
        "feature_types": ["TABLES", "LAYOUT"],
        "pages": pages,
        "lines": lines,
        "words": words,
        "tables": tables,
        "layout_elements": layout_elements,
        "raw_block_count": len(blocks),
    }
